-- Trip: plate seen at a sequence of junctions (aggregated from its cameras)
INSERT INTO sightings (source_event_id, camera_id, plate_id, raw_plate_text, normalized_plate_candidate, detection_confidence, ocr_confidence, ocr_candidates, validation_status, spotted_at, direction_degrees, vehicle_type, vehicle_color, lane_number, model_version)
VALUES
  ('seed-DL3CAB1234-JCT-01', (SELECT camera_id FROM cameras WHERE camera_code='JCT-01'), (SELECT plate_id FROM plates WHERE normalized_plate='DL3CAB1234'), 'DL3CAB1234', 'DL3CAB1234', 0.96, 0.93, '[]'::jsonb, 'accepted', now() - make_interval(secs => 376), 165, 'car', 'white', 2, 'anpr-v1'),
  ('seed-DL3CAB1234-JCT-02', (SELECT camera_id FROM cameras WHERE camera_code='JCT-02'), (SELECT plate_id FROM plates WHERE normalized_plate='DL3CAB1234'), 'DL3CAB1234', 'DL3CAB1234', 0.96, 0.93, '[]'::jsonb, 'accepted', now() - make_interval(secs => 261), 165, 'car', 'white', 2, 'anpr-v1'),
  ('seed-DL3CAB1234-JCT-03', (SELECT camera_id FROM cameras WHERE camera_code='JCT-03'), (SELECT plate_id FROM plates WHERE normalized_plate='DL3CAB1234'), 'DL3CAB1234', 'DL3CAB1234', 0.96, 0.93, '[]'::jsonb, 'accepted', now() - make_interval(secs => 199), 127, 'car', 'white', 2, 'anpr-v1'),
  ('seed-DL3CAB1234-JCT-07', (SELECT camera_id FROM cameras WHERE camera_code='JCT-07'), (SELECT plate_id FROM plates WHERE normalized_plate='DL3CAB1234'), 'DL3CAB1234', 'DL3CAB1234', 0.96, 0.93, '[]'::jsonb, 'accepted', now() - make_interval(secs => 128), 127, 'car', 'white', 2, 'anpr-v1'),
  ('seed-DL3CAB1234-JCT-05', (SELECT camera_id FROM cameras WHERE camera_code='JCT-05'), (SELECT plate_id FROM plates WHERE normalized_plate='DL3CAB1234'), 'DL3CAB1234', 'DL3CAB1234', 0.96, 0.93, '[]'::jsonb, 'accepted', now() - make_interval(secs => 64), 216, 'car', 'white', 2, 'anpr-v1'),
